26: ['O pergaminho esquecido','Na biblioteca, você encontra um pergaminho de exercícios básicos de chakra. O instrutor está ocupado.','Estudar em silêncio|+3 ninjutsu,+2 intel','Levar para o instrutor|+2 bond,+2 renown','Chamar um colega para estudar|+1 intel,+3 bond'],
27: ['Um almoço solitário','Hinata está sentada sozinha no pátio. Naruto tenta equilibrar uma bandeja na cabeça.','Sentar com Hinata|+4 bond,+1 intel','Ajudar Naruto com a bandeja|+3 bond,+1 renown','Treinar no pátio|+2 taijutsu,+2 energy'],
28: ['A rivalidade começa','Sasuke acerta um alvo difícil e todos aplaudem. Você sente a vontade de provar seu valor.','Pedir dicas a ele|+3 bond,+2 intel','Desafiá-lo para uma corrida|+3 taijutsu,+2 renown','Parabenizar e voltar a treinar|+2 bond,+2 ninjutsu'],
29: ['Festival da Vila','Lanternas coloridas tomam as ruas. Você recebeu alguns ryō para gastar como quiser.','Comprar dangos para dividir|-10 ryo,+4 bond','Assistir à demonstração de jutsu|-5 ryo,+3 ninjutsu','Guardar o dinheiro|+15 ryo,+1 intel']];
30: if(state.age<13)return[
31: ['A graduação se aproxima','A prova da Academia está chegando. O instrutor anuncia um teste de transformação para a turma.','Treinar até acertar|+4 ninjutsu,-8 energy','Estudar fundamentos|+3 intel,+2 chakra','Acalmar um colega nervoso|+3 bond,+1 renown'],
32: ['Trabalho em equipe','Seu time precisa atravessar um campo de obstáculos sem deixar ninguém para trás.','Liderar o grupo|+3 renown,+2 bond','Observar e encontrar uma rota|+4 intel,+1 energy','Ajudar quem ficou para trás|+4 bond,+2 energy'],
33: ['Um dia de treino','Kakashi passa pela Academia e deixa uma dica enigmática sobre concentração.','Praticar controle de chakra|+4 chakra,+2 ninjutsu','Desafiar o boneco de treino|+4 taijutsu,-7 energy','Perguntar sobre trabalho em equipe|+3 intel,+3 bond'],
34: ['O exame final','Você faz o selo da transformação diante dos examinadores. Todos aguardam o resultado.','Respirar e confiar no treino|+3 ninjutsu,+3 renown','Improvisar uma transformação criativa|+3 intel,+4 renown','Pensar no que sua equipe precisa|+4 bond,+2 renown']];
35: if(state.age<18)return[
36: ['Primeira missão de verdade','Seu time recebe uma missão simples fora da vila. Um contratante parece esconder parte da história.','Investigar antes de agir|+3 intel,+3 renown','Confiar no líder da equipe|+3 bond,+2 energy','Concluir rápido e voltar|+3 taijutsu,+4 ryo'],
37: ['Treino com o time','Seu sensei propõe um exercício de sobrevivência. O objetivo não é vencer: é aprender a cooperar.','Proteger o companheiro|+4 bond,+2 renown','Armar uma estratégia|+4 intel,+1 chakra','Atacar com tudo|+4 taijutsu,-10 energy'],
38: ['Um rumor no mercado','Mercadores falam de ninjas desconhecidos rondando a fronteira. Talvez seja só conversa.','Relatar ao gabinete|+3 renown,+2 bond','Investigar com cuidado|+3 intel,+5 ryo','Ignorar e aproveitar o dia|+8 energy,+2 bond'],
39: ['O caminho do ninja','Um colega pergunta o que você espera da vida shinobi. Sua resposta surpreende até você.','Ser forte o bastante para proteger|+3 bond,+3 taijutsu','Descobrir todos os jutsus possíveis|+3 chakra,+3 ninjutsu','Escolher seu próprio caminho|+3 intel,+3 renown']];
40: return[
41: ['Uma missão de alto risco',`O gabinete oferece uma missão rank ${state.age>25?'A':'B'} além das fronteiras. A equipe está contando com você.`,'Aceitar e liderar|+5 renown,+4 ryo,-12 energy','Planejar cada detalhe|+4 intel,+2 renown','Pedir reforços para o time|+4 bond,+2 renown'],
42: ['Um velho rival','Você reencontra Sasuke numa estrada distante. Há muito a dizer, mas o silêncio pesa.','Conversar sem levantar a guarda|+5 bond,+2 intel','Propor um duelo amistoso|+4 taijutsu,+3 renown,-8 energy','Seguir viagem em paz|+3 intel,+4 energy'],
43: ['Convite para ensinar','A Academia precisa de alguém para orientar a nova geração. Você se lembra de como tudo começou.','Aceitar como sensei|+5 bond,+5 renown,-5 ryo','Dar uma aula especial|+4 intel,+3 renown','Ainda não é a hora|+5 energy,+3 ryo'],
44: ['Escolhas de um líder','Uma decisão difícil divide a vila. A solução mais fácil pode custar a confiança de alguém.','Ouvir todas as partes|+4 bond,+4 intel','Decidir pelo bem maior|+5 renown,+3 bond','Adiar e buscar outra saída|+3 intel,-2 renown'],
45: ['Paz também é uma missão','Por um tempo, não há alarmes nem chamados urgentes. O que fazer com esse raro silêncio?','Visitar quem você ama|+5 bond,-8 ryo','Pesquisar uma técnica nova|+4 ninjutsu,+2 chakra,-6 ryo','Descansar sem culpa|+15 energy,+2 bond']];}
46: function nextEvent(){const pool=eventPool();let idx=Math.floor(Math.random()*pool.length);if(pool.length>1&&idx===state.eventIndex)idx=(idx+1)%pool.length;state.eventIndex=idx;const e=pool[idx];return{title:e[0],text:e[1],choices:e.slice(2).map(s=>{const [label,effect]=s.split('|');return{label,effect}})};}
47: const actions=[
48: {icon:'◈',title:'Treinar',hint:'Aprimore uma habilidade',run(){const skills=['taijutsu','ninjutsu','chakra'];const sk=skills[Math.floor(Math.random()*skills.length)];state[sk]+=5;state.energy-=14;return `Treino intenso: +5 ${skillLabel(sk)}.`}},
49: {icon:'⌕',title:'Estudar',hint:'Conhecimento e estratégia',run(){state.intel+=5;state.energy-=7;return'Você estudou táticas e teoria ninja. +5 inteligência.'}},
50: {icon:'♡',title:'Conviver',hint:'Fortaleça uma amizade',run(){let r=state.relations[Math.floor(Math.random()*state.relations.length)];r.value=clamp(r.value+9);state.bond+=3;state.energy-=4;return`Um bom momento com ${r.name}. +9 amizade.`}},
51: {icon:'⚑',title:'Fazer missão',hint:'Ganhe ryō e reputação',run(){if(state.age<12)return null;let success=state.intel+state.taijutsu+state.ninjutsu+state.chakra>150;state.ryo+=success?28:12;state.renown+=success?5:2;state.energy-=22;if(!success)state.health=state.health||100;return success?'Missão concluída com mérito. +28 ryō, +5 reputação.':'A missão foi complicada, mas voltou em segurança. +12 ryō, +2 reputação.'}},
52: {icon:'⌂',title:'Descansar',hint:'Recupere energia',run(){state.energy=clamp(state.energy+27);state.bond+=1;return'Um dia tranquilo devolveu suas forças. +27 energia.'}},
53: {icon:'◉',title:'Explorar',hint:'Descubra algo inesperado',run(){const finds=['Você ouviu histórias de viajantes. +2 inteligência.','Um comerciante pagou por sua ajuda. +18 ryō.','Encontrou um lugar calmo para meditar. +4 chakra.','Ajudou um morador e ganhou sua confiança. +3 reputação.'];let n=Math.floor(Math.random()*finds.length);if(n===0)state.intel+=2;if(n===1)state.ryo+=18;if(n===2)state.chakra+=4;if(n===3)state.renown+=3;state.energy-=5;return finds[n]}}
54: ];
55: function doAction(i){if(state.finished||state.activities>=2||(state.energy<5&&i!==4)){toast(state.activities>=2?'Você já aproveitou suas duas atividades deste ano.':'Energia baixa — tente descansar.');return}const result=actions[i].run();if(!result){toast('Missões ninja ficam disponíveis a partir dos 12 anos.');return}state.activities++;state.energy=clamp(state.energy);state.ryo=Math.max(0,state.ryo);addJournal(result);save();render();toast(result)}
56: function applyEffect(effect){for(const part of effect.split(',')){const m=part.match(/^([+-])(\d+)\s+(\w+)$/);if(!m)continue;const amount=Number(m[2])*(m[1]==='-'?-1:1),key=m[3];if(key==='ryo')state.ryo=Math.max(0,state.ryo+amount);else if(key==='energy')state.energy=clamp(state.energy+amount);else if(key==='bond'){state.bond=clamp(state.bond+amount);if(state.relations.length)state.relations[0].value=clamp(state.relations[0].value+Math.ceil(amount/2))}else state[key]=clamp((state[key]||0)+amount)} }
57: function choose(i){const c=state.event.choices[i];applyEffect(c.effect);addJournal(`${state.event.title}: ${c.label}.`);state.activities=0;state.age++;if(state.age===13)state.phase='Genin';if(state.age===16)state.phase='Chūnin';if(state.age===20)state.phase='Jōnin';if(state.age===65)state.phase='Ancião';if(state.age>=85){state.finished=true;state.phase='Lenda';}state.energy=clamp(state.energy+8);state.event=state.finished?null:nextEvent();save();render();}
58: function skillLabel(key){return{taijutsu:'taijutsu',ninjutsu:'ninjutsu',chakra:'chakra'}[key]||key}
59: function stat(label,key,color=''){let value=clamp(state[key]);return `<div class="stat"><div class="stat-label"><span>${label}</span><b>${value}</b></div><div class="bar ${color}"><i style="width:${value}%"></i></div></div>`}
