ate');save();render();toast(text);}function setRogue(){if(state.rogue)return;state.rogue=true;state.bond=clamp(state.bond-8);state.renown+=2;addJournal(`Você abandonou ${state.village} e passou a viver como ninja rogue (nukenin).`);save();}function becomeRogue(){if(state.rogue)return;if(confirm(`Abandonar ${state.village} e se tornar um ninja rogue (nukenin)? Essa escolha muda suas missões e sua vida na vila.`)){setRogue();render();toast('Você agora é um nukenin. Sua antiga vila pode enviar perseguidores.');}}function doAction(i){if(state.combat){toast('Conclua o combate atual antes de fazer outra atividade.');return}if(state.finished||state.activities>=2||(state.energy<5&&i!==4)){ toast(state.activities>=2?'Você já aproveitou suas duas atividades deste ano.':'Energia baixa — tente descansar.');return}const before=progressSnapshot();const result=actions[i].run();if(!result){toast('Missões ninja ficam disponíveis a partir dos 12 anos.');return}state.activities++;state.energy=clamp(state.energy);state.ryo=Math.max(0,state.ryo);const details=result+progressSummary(before);addJournal(details,'Atividade');save();render();toast(details)}
